// Lecture d'un export de report Salesforce (« .xls » qui est en réalité un
// tableau HTML, ou CSV). Fonctions pures (testées dans tests/salesforce-report.test.js),
// plus readLeadsReport(file) côté navigateur.
//
// Seules les colonnes société / statut / campagne / ID du lead / DUNS / ville sont
// lues : jamais de nom de collaborateur Dell (propriétaire, « Generated By »…).
import { normalizeLeadStatus } from "./salesforce-leads.js";

const NAMED = {
  amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ", rsquo: "’", laquo: "«", raquo: "»",
  eacute: "é", egrave: "è", ecirc: "ê", euml: "ë", agrave: "à", acirc: "â", ccedil: "ç",
  icirc: "î", iuml: "ï", ocirc: "ô", ugrave: "ù", ucirc: "û", uuml: "ü", Eacute: "É",
};

function unescapeHtml(s) {
  return String(s || "")
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&([a-z]+);/gi, (m, n) => NAMED[n] ?? NAMED[n.toLowerCase()] ?? m);
}

const cellText = (html) => unescapeHtml(String(html).replace(/<br\s*\/?>/gi, " ").replace(/<[^>]*>/g, ""))
  .replace(/\s+/g, " ").trim();

/** Tableau HTML → { headers, rows } (première ligne de <th>, ou première ligne). */
export function parseHtmlTable(text) {
  const trs = [...String(text || "").matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)].map((m) => m[1]);
  const table = trs.map((tr) => [...tr.matchAll(/<t([hd])[^>]*>([\s\S]*?)<\/t[hd]>/gi)].map((m) => ({ th: m[1].toLowerCase() === "h", text: cellText(m[2]) })))
    .filter((cells) => cells.length);
  if (!table.length) return { headers: [], rows: [] };
  const headIdx = Math.max(0, table.findIndex((cells) => cells.some((c) => c.th)));
  return {
    headers: table[headIdx].map((c) => c.text),
    rows: table.slice(headIdx + 1).map((cells) => cells.map((c) => c.text)),
  };
}

/** CSV (séparateur , ; ou tabulation, guillemets) → { headers, rows }. */
export function parseCsv(text) {
  const src = String(text || "").replace(/^﻿/, "");
  const firstLine = src.split(/\r?\n/, 1)[0] || "";
  const sep = [",", ";", "\t"].sort((a, b) => firstLine.split(b).length - firstLine.split(a).length)[0];
  const rows = [];
  let row = [];
  let cell = "";
  let quoted = false;
  for (let i = 0; i < src.length; i++) {
    const ch = src[i];
    if (quoted) {
      if (ch === '"' && src[i + 1] === '"') { cell += '"'; i++; }
      else if (ch === '"') quoted = false;
      else cell += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === sep) { row.push(cell); cell = ""; }
    else if (ch === "\n" || ch === "\r") {
      if (ch === "\r" && src[i + 1] === "\n") i++;
      row.push(cell); rows.push(row); row = []; cell = "";
    } else cell += ch;
  }
  if (cell || row.length) { row.push(cell); rows.push(row); }
  const clean = rows.map((r) => r.map((c) => c.replace(/\s+/g, " ").trim())).filter((r) => r.some(Boolean));
  return { headers: clean[0] || [], rows: clean.slice(1) };
}

const norm = (s) => String(s || "").normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();

// Colonnes reconnues (intitulés anglais ou français).
const COLUMNS = {
  company: /^(company( \/ account)?|account( name)?|compte|nom du compte|societe|entreprise|raison sociale)$/,
  status: /^(lead status|status|statut( du lead)?)$/,
  sf_lead_id: /^(lead tracking id|lead id|id du lead|lead tracking number)$/,
  duns: /duns/,
  campaign: /^(campaign( short name| name)?|campagne)$/,
  city: /^(city|ville|commune|billing city)$/,
  postal: /^(zip|zip\/postal code|postal code|code postal|billing zip\/postal code)$/,
};

/**
 * Colonnes d'un report → lignes de leads au format de l'import PDF
 * ({ company, status, campaign, contact, account, created }) + sf_lead_id, duns, city.
 */
export function reportToLeads({ headers, rows }) {
  const head = (headers || []).map(norm);
  const idx = Object.fromEntries(Object.entries(COLUMNS).map(([k, re]) => [k, head.findIndex((h) => re.test(h))]));
  if (idx.company < 0) {
    return { rows: [], diagnostic: { headers: headers || [], error: "colonne société introuvable" } };
  }
  const get = (r, k) => (idx[k] >= 0 ? String(r[idx[k]] || "").trim() : "");
  const out = [];
  for (const r of rows || []) {
    // Lignes de pied de report (titre, totaux, copyright, « Generated By »…) :
    // une seule cellule ou presque. Elles ne sont jamais lues.
    if (head.length > 1 && r.length < Math.ceil(head.length / 2)) continue;
    const company = get(r, "company").slice(0, 200);
    if (!company || /^(total|grand total|sous-total|copyright|confidential|generated by)/i.test(company)) continue;
    const id = get(r, "sf_lead_id");
    out.push({
      company,
      status: normalizeLeadStatus(get(r, "status")) || "New",
      campaign: get(r, "campaign").slice(0, 80),
      sf_lead_id: /^[A-Za-z0-9_-]{4,40}$/.test(id) ? id : "",
      duns: get(r, "duns").replace(/\D/g, "").slice(0, 12),
      city: get(r, "city").slice(0, 80),
      postal: get(r, "postal").replace(/\s/g, "").slice(0, 10),
      contact: "",
      account: company,
      created: null,
    });
  }
  return { rows: out, diagnostic: { headers: headers || [], columns: Object.keys(idx).filter((k) => idx[k] >= 0) } };
}

/** Texte d'un fichier : UTF-8 si possible (ou si annoncé), sinon Windows-1252 (exports Excel). */
export function decodeReport(bytes) {
  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  const head = new TextDecoder("latin1").decode(u8.slice(0, 1024));
  const declared = /charset=["']?([\w-]+)/i.exec(head)?.[1]?.toLowerCase();
  if (declared && declared !== "utf-8" && declared !== "utf8") {
    return new TextDecoder("windows-1252").decode(u8);
  }
  try { return new TextDecoder("utf-8", { fatal: true }).decode(u8); } catch { return new TextDecoder("windows-1252").decode(u8); }
}

/** Contenu de report (texte) → leads. HTML (.xls Salesforce) ou CSV. */
export function parseReportText(text) {
  const isHtml = /<table[\s>]/i.test(String(text).slice(0, 5000));
  return reportToLeads(isHtml ? parseHtmlTable(text) : parseCsv(text));
}

/** Côté navigateur : lit un export de report (.xls HTML ou .csv). */
export async function readLeadsReport(file) {
  const buf = new Uint8Array(await file.arrayBuffer());
  if (buf[0] === 0x50 && buf[1] === 0x4b) {
    throw new Error("Fichier Excel « .xlsx » : exporte le report en « .xls » (comme le fichier d'origine) ou en « .csv ».");
  }
  return parseReportText(decodeReport(buf));
}
